# Compare fields while preserving lists and values; do not hide version-only differences.
def diff(a,b,path=''):
 if type(a)!=type(b):return [{'path':path,'old':a,'new':b}]
 if isinstance(a,dict):return [d for k in sorted(set(a)|set(b)) for d in diff(a.get(k),b.get(k),path+'/'+k)]
 if isinstance(a,list) and len(a)==len(b):return [d for i,(x,y) in enumerate(zip(a,b)) for d in diff(x,y,path+'/'+str(i))]
